import type { PathArray, Point } from "../types.ts";
import type { PointProperties } from "../interface.ts";
import { buildPathLengthTable, getPointAtTable } from "./pathLengthTable.ts";
import { getPropertiesAtLength } from "./getPropertiesAtLength.ts";
import { parsePathString } from "../parser/parsePathString.ts";
import { normalizePath } from "../process/normalizePath.ts";

/**
 * Returns the point and segment in path closest to a given point as well as
 * the distance to the path stroke.
 *
 * @see https://bl.ocks.org/mbostock/8027637
 *
 * @param pathInput target `pathArray`
 * @param point the given point
 * @returns the requested properties
 */
export const getPropertiesAtPoint = <T extends PathArray>(
  pathInput: string | T,
  point: Point,
): PointProperties => {
  const path = parsePathString(pathInput);
  // an empty path has no closest point
  if (!path.length) {
    return { closest: { x: 0, y: 0 }, distance: Infinity };
  }
  const normalPath = normalizePath(path);
  // the length table is built once and serves every sample of the search
  const table = buildPathLengthTable(normalPath);
  const pathLength = table.totalLength;
  // a loop ends where it starts, so the search can walk over the end of the
  // path and find the other side of the join
  const isLoop = table.isLoop;
  const distanceTo = (p: Point) => {
    const dx = p.x - point.x;
    const dy = p.y - point.y;
    return dx * dx + dy * dy;
  };
  let precision = 8;
  let scan: Point;
  let closest = { x: 0, y: 0 }; // make TS happy
  let scanDistance = 0;
  let bestLength = 0;
  let bestDistance = Infinity;

  // linear scan for coarse approximation
  for (let scanLength = 0; scanLength <= pathLength; scanLength += precision) {
    scan = getPointAtTable(table, scanLength);
    scanDistance = distanceTo(scan);

    if (scanDistance < bestDistance) {
      closest = scan;
      bestLength = scanLength;
      bestDistance = scanDistance;
    }
  }

  // binary search for precise estimate
  precision /= 2;
  let beforeLength = 0;
  let afterLength = 0;

  while (precision > 0.000001) {
    beforeLength = bestLength - precision;
    afterLength = bestLength + precision;
    // a loop is walked over its end, an open path is not
    if (beforeLength < 0) {
      beforeLength = isLoop ? beforeLength + pathLength : -1;
    }
    if (afterLength > pathLength) {
      afterLength = isLoop ? afterLength - pathLength : pathLength + 1;
    }

    const before =
      beforeLength >= 0 && beforeLength <= pathLength ? getPointAtTable(table, beforeLength) : null;
    const after =
      afterLength >= 0 && afterLength <= pathLength ? getPointAtTable(table, afterLength) : null;
    const beforeDistance = before ? distanceTo(before) : Infinity;
    const afterDistance = after ? distanceTo(after) : Infinity;

    if (before && beforeDistance < bestDistance) {
      closest = before;
      bestLength = beforeLength;
      bestDistance = beforeDistance;
    } else if (after && afterDistance < bestDistance) {
      closest = after;
      bestLength = afterLength;
      bestDistance = afterDistance;
    } else {
      precision /= 2;
    }
    if (precision < 0.00001) break;
  }

  const segment = getPropertiesAtLength(path, bestLength);
  const distance = Math.sqrt(bestDistance);

  return { closest, distance, segment };
};
